-- 		UPDATE fpsm set [data] = case when coalesce(outerCte.dataElement,[data]) is null then @lastCleaning else @lastCleaning + ',' + coalesce(outerCte.dataElement,[data]) END, updatedAt = getdate() FROM MR3.FunctionPlaceStatusMap fpsm 
