-- CREATE PROC [MRA3].[SchedulerCreateScheduleForFacility]

-- 	@facilityId uniqueidentifier,
-- 	@date date

-- AS
-- BEGIN


-- 	UPDATE MRA3.TempSchedulerStaffSchedule set assignedToAsset = null 
-- 		WHERE facilityId = @facilityId
-- 		AND schedDate = @date 

-- 	-- clean out any previous assignments
-- 	UPDATE MRA3.TempSchedulerAssets set assignedTo = null, assignedToPriority = null, requestType = null, aggregateScore = null 
-- 		WHERE FacilityId = @facilityId;
	
-- 	-- place all staff who have been assigned to a desk in that desk
-- 	-- the common table expression is there to handle cases where more than one staff
-- 	-- member is assigned to one desk. In this case we take the highest priority
-- 	-- staff member and assign them on that given day
-- 	with cte as (select ROW_NUMBER() OVER (Partition by s.assignedTo_pointId order by s.rowNum desc) as prio, * 
-- 		FROM MRA3.TempSchedulerStaffSchedule s 
-- 		WHERE s.facilityId = @facilityId 
-- 		  AND schedDate = @date 
-- 		  AND s.assignedTo_pointId is not null
-- 		  AND s.aggregateScore > 0
-- 		)
-- 	UPDATE asset set assignedTo = staff.staffId, assignedToPriority = staff.rowNum, requestType = 0, aggregateScore = staff.aggregateScore
-- 	FROM MRA3.TempSchedulerAssets asset 
-- 	INNER JOIN cte staff  on staff.assignedTo_pointId = asset.PointId AND staff.prio = 1
-- 	WHERE asset.facilityId = @facilityId
-- 			AND asset.availableForUse !=0 
-- 			AND asset.includeInCapacityCount = 1 
-- 			AND asset.isHotDesk = 0 
-- 			AND staff.schedDate = @date
-- 			AND asset.socDistFunctionStatusCode != 'SOCIALDIST>CLOSED';

-- 	UPDATE staff set assignedToAsset = asset.PointId 
-- 	FROM MRA3.TempSchedulerStaffSchedule staff 
-- 	INNER JOIN MRA3.TempSchedulerAssets asset on asset.assignedTo = staff.staffId


-- 	-- TODO: Based on priority, remove anyone from a desk where there is a dynamic social distance rule conflict

-- 	-- apply capacity limits to take anyone who is in a fixed desk that breaks the capacity limit
-- 	-- deassign them from that desk/room/floorplan, etc AND put them back into the pool to be assigned
-- 	-- to a hot desk.
-- 	EXEC MRA3.SchedulerApplyFacilityCapacityLimits @facilityId = @facilityId, @date = @date

-- 	-- Create a list of the remaining staff AND the locations they have favorited plus where they have been assigned
-- 	-- The requestType field allows us to place higher priority in assigning someone to a desk they have 
-- 	-- selected. We give highest priority to the desk they have chosen, then we look at all of the desks in a room that
-- 	-- they have selected AND so on.  Ultimately, if they have not selected anything, we start to look 
-- 	-- at where they have been assigned
-- 	SELECT x.* into #staffPlaceRequests
-- 	FROM (
-- 			SELECT 
-- 				sppm.SppmStaffId as staffId,
-- 				staff.rowNum,
-- 				staff.aggregateScore,
-- 				-- this case statement helps us prioritize assignments,
-- 				-- if someone has reserved a desk AND it is avaiable, give it to them
-- 				-- if none are available, but they have reserved a room, give them a
-- 				-- desk from the room, etc.
-- 				case when sppm.sppmPointId is not null then 1
-- 						when sppm.SppmRoomId is not null then 2
-- 						when sppm.SppmFloorplanId is not null then 3
-- 						when sppm.SppmBuildingId is not null then 4
-- 						else 5 -- for facilities
-- 				end as requestType,
-- 				sppm.SppmPointId as pointId,
-- 				sppm.SppmRoomId as roomId,
-- 				sppm.SppmFloorplanId as floorplanId,
-- 				sppm.SppmBuildingId as buildingId,
-- 				sppm.SppmFacilityId as facilityId
			
-- 			FROM MR3.StaffPlacePreferenceMap sppm
-- 			INNER JOIN MRA3.TempSchedulerStaffSchedule staff on staff.facilityId = @facilityId AND sppm.SppmStaffId = staff.staffId
-- 			WHERE staff.assignedToAsset is null 
-- 					AND sppm.SppmPreferenceLevel > 0 
-- 					AND staff.schedDate = @date 
-- 					AND staff.aggregateScore > 0

-- 			UNION 

-- 			-- lower in priority, check the room they have been assigned to 
-- 			-- AND see if there are any desks there
-- 			SELECT 
-- 				staffId, 
-- 				rowNum, 
-- 				staff.aggregateScore,
-- 				6 as requestType,
-- 				null as pointId,
-- 				staff.assignedTo_roomId as roomId, 
-- 				staff.assignedTo_floorplanId as floorplanId, 
-- 				staff.assignedTo_buildingId as buildingId,
-- 				staff.assignedTo_facilityId as facilityId
-- 				FROM MRA3.TempSchedulerStaffSchedule staff 
-- 				WHERE staff.facilityId = @facilityId
-- 					AND staff.schedDate = @date 
-- 					AND staff.assignedToAsset IS NULL
-- 					AND staff.aggregateScore > 0

-- 			UNION

-- 			-- AND even lower in priority, check the floorplan they have been assigned to 
-- 			-- AND see if there are any desks there
-- 			SELECT 
-- 				staffId, 
-- 				rowNum, 
-- 				staff.aggregateScore,
-- 				7 as requestType,
-- 				null as pointId,
-- 				null as roomId, 
-- 				staff.assignedTo_floorplanId as floorplanId, 
-- 				staff.assignedTo_buildingId as buildingId,
-- 				staff.assignedTo_facilityId as facilityId
-- 				FROM MRA3.TempSchedulerStaffSchedule staff 
-- 				WHERE staff.facilityId = @facilityId
-- 					AND staff.schedDate = @date 
-- 					AND staff.assignedToAsset IS NULL
-- 					AND staff.aggregateScore > 0

-- 			UNION

-- 			-- check the building they have been assigned to 
-- 			-- AND see if there are any desks there
-- 			SELECT 
-- 				staffId, 
-- 				rowNum, 
-- 				staff.aggregateScore,
-- 				8 as requestType,
-- 				null as pointId,
-- 				null as roomId, 
-- 				null as floorplanId, 
-- 				staff.assignedTo_buildingId as buildingId,
-- 				staff.assignedTo_facilityId as facilityId
-- 				FROM MRA3.TempSchedulerStaffSchedule staff 
-- 				WHERE staff.facilityId = @facilityId
-- 					AND staff.schedDate = @date 
-- 					AND staff.assignedToAsset IS NULL
-- 					AND staff.aggregateScore > 0

-- 			UNION

-- 			-- check the building they have been assigned to 
-- 			-- AND see if there are any desks there
-- 			SELECT 
-- 				staffId, 
-- 				rowNum, 
-- 				staff.aggregateScore,
-- 				9 as requestType,
-- 				null as pointId,
-- 				null as roomId, 
-- 				null as floorplanId, 
-- 				null as buildingId,
-- 				staff.assignedTo_facilityId as facilityId
-- 				FROM MRA3.TempSchedulerStaffSchedule staff 
-- 				WHERE staff.facilityId = @facilityId
-- 					AND staff.schedDate = @date 
-- 					AND staff.assignedToAsset IS NULL
-- 					AND staff.aggregateScore > 0
				
-- 		) x
				

-- 	DECLARE @staffId uniqueidentifier,
-- 			@pointId uniqueidentifier,
-- 			@rowNum int,
-- 			@requestType int,
-- 			@counter int,
-- 			@minRowNum int,
-- 			@aggregateScore int

-- 	SET @counter = 0


-- 	--select * from #staffPlaceRequests order by rowNum

-- 	-- Go in priority order AND assign hot desks to staff
-- 	WHILE (1 = 1)
-- 	BEGIN

-- 		SET @counter = @counter + 1
-- 		SET @staffId = null
-- 		SET @minRowNum = null
-- 		SET @aggregateScore = null

-- 		SELECT top 1 @minRowNum = rowNum from #staffPlaceRequests order by rowNum

-- 		if (@minRowNum is null) BREAK

-- 		-- start with the highest priority staff member
-- 		-- look at their favorite places, resolve these into hot desks
-- 		-- choose the item that is reserved at the most granular level 
-- 		-- (i.e. choose a desk that was reserved as a desk preference before assigning a desk that 
-- 		-- was part of a room preference)

-- 		-- start by trying to assign this staff member to a desk they have selected as a preference
-- 		select top 1 
-- 			@staffId = staffId, 
-- 			@pointId = place.pointId, 
-- 			@rowNum = rowNum, 
-- 			@requestType = s.requestType,
-- 			@aggregateScore = s.aggregateScore
-- 		FROM #staffPlaceRequests s
-- 		INNER JOIN MRA3.TempSchedulerPlaceList place on  
-- 			place.FacilityId = @facilityId 
-- 			AND place.pointId = s.pointId -- try to assign to a point first
-- 		INNER JOIN MRA3.TempSchedulerAssets asset on asset.facilityId = @facilityId AND place.pointId = asset.PointId
-- 		WHERE asset.isHotDesk = 1 
-- 				AND asset.availableForUse != 0 
-- 				AND asset.assignedTo is null 
-- 				AND asset.socDistFunctionStatusCode != 'SOCIALDIST>CLOSED'
-- 		AND s.rowNum = @minRowNum
-- 		order by s.requestType, cast(asset.pointId as nvarchar(50))


-- 		-- if we were unable to assign to a desk, let's try to assign to a desk in a room that 
-- 		-- they have set as a preference or the room they are assigned to
-- 		if (@staffId is null)
-- 			BEGIN
-- 			select top 1 
-- 				@staffId = staffId, 
-- 				@pointId = place.pointId, 
-- 				@rowNum = rowNum, 
-- 				@requestType = s.requestType,
-- 				@aggregateScore = s.aggregateScore
-- 			FROM #staffPlaceRequests s
-- 			INNER JOIN MRA3.TempSchedulerPlaceList place on  
-- 				place.FacilityId = @facilityId 
-- 				AND s.pointId is null AND s.roomId = place.roomId -- now let's try to assign to a room if no point was found by looking at all desks in the room
-- 			INNER JOIN MRA3.TempSchedulerAssets asset on asset.facilityId = @facilityId AND place.pointId = asset.PointId
-- 			WHERE asset.isHotDesk = 1 
-- 					AND asset.availableForUse != 0 
-- 					AND asset.assignedTo is null 
-- 					AND asset.socDistFunctionStatusCode != 'SOCIALDIST>CLOSED'
-- 			AND s.rowNum = @minRowNum
-- 			order by s.requestType, cast(asset.pointId as nvarchar(50))
-- 		END

-- 		-- if we were unable to assign to a desk, let's try to assign to a desk in a floor that 
-- 		-- they have set as a preference or the floor they are assigned to
-- 		if (@staffId is null)
-- 			BEGIN
-- 			select top 1 
-- 				@staffId = staffId, 
-- 				@pointId = place.pointId, 
-- 				@rowNum = rowNum, 
-- 				@requestType = s.requestType,
-- 				@aggregateScore = s.aggregateScore
-- 			FROM #staffPlaceRequests s
-- 			INNER JOIN MRA3.TempSchedulerPlaceList place on  
-- 				place.FacilityId = @facilityId 
-- 				-- now let's try to assign to a floorplan if no point was found by looking at all desks in the floorplan
-- 				AND s.pointId is null AND s.roomId is null AND s.floorplanId = place.floorplanId 
-- 			INNER JOIN MRA3.TempSchedulerAssets asset on asset.facilityId = @facilityId AND place.pointId = asset.PointId
-- 			WHERE asset.isHotDesk = 1 
-- 					AND asset.availableForUse != 0 
-- 					AND asset.assignedTo is null 
-- 					AND asset.socDistFunctionStatusCode != 'SOCIALDIST>CLOSED'
-- 			AND s.rowNum = @minRowNum
-- 			order by s.requestType, cast(asset.pointId as nvarchar(50))
-- 		END

-- 		-- now by building
-- 		if (@staffId is null)
-- 			BEGIN
-- 			select top 1 
-- 				@staffId = staffId, 
-- 				@pointId = place.pointId, 
-- 				@rowNum = rowNum, 
-- 				@requestType = s.requestType,
-- 				@aggregateScore = s.aggregateScore
-- 			FROM #staffPlaceRequests s
-- 			INNER JOIN MRA3.TempSchedulerPlaceList place on
-- 				place.FacilityId = @facilityId 
-- 				-- now let's try to assign to a building if no point was found by looking at all desks in the building
-- 				AND s.pointId is null AND s.roomId is null AND s.floorplanId IS NULL AND s.buildingId = place.BuildingId
-- 			INNER JOIN MRA3.TempSchedulerAssets asset on asset.facilityId = @facilityId AND place.pointId = asset.PointId
-- 			WHERE asset.isHotDesk = 1 
-- 					AND asset.availableForUse != 0 
-- 					AND asset.assignedTo is null 
-- 					AND asset.socDistFunctionStatusCode != 'SOCIALDIST>CLOSED'
-- 			AND s.rowNum = @minRowNum
-- 			order by s.requestType, cast(asset.pointId as nvarchar(50))
-- 		END

-- 		-- and finally, look at the whole facility
-- 		if (@staffId is null)
-- 			BEGIN
-- 			select top 1 
-- 				@staffId = staffId, 
-- 				@pointId = place.pointId, 
-- 				@rowNum = rowNum, 
-- 				@requestType = s.requestType,
-- 				@aggregateScore = s.aggregateScore
-- 			FROM #staffPlaceRequests s
-- 			INNER JOIN MRA3.TempSchedulerPlaceList place on  -- this decomposes favorite requests for rooms, floors, buildings AND facilities into individual points
-- 				place.FacilityId = @facilityId 
-- 				AND s.pointId is null AND s.roomId is null AND s.floorplanId IS NULL AND s.buildingId IS NULL and s.facilityId = place.FacilityId
-- 			INNER JOIN MRA3.TempSchedulerAssets asset on asset.facilityId = @facilityId AND place.pointId = asset.PointId
-- 			WHERE asset.isHotDesk = 1 
-- 					AND asset.availableForUse != 0 
-- 					AND asset.assignedTo is null 
-- 					AND asset.socDistFunctionStatusCode != 'SOCIALDIST>CLOSED'
-- 			AND s.rowNum = @minRowNum
-- 			order by s.requestType, cast(asset.pointId as nvarchar(50))
-- 		END

-- 		-- at this point, if we arrive here, we are out of desk options, so stop looking
	
-- 		IF ((@staffId is null) OR (@counter > 20000)) BREAK  -- set a max of 20000 iterations to prevent possible infinite loops in case the logic goes wrong

-- 		UPDATE asset set assignedTo = @staffId, assignedToPriority = @rowNum, requestType = @requestType, aggregateScore = @aggregateScore
-- 		FROM MRA3.TempSchedulerAssets asset 
-- 		WHERE asset.FacilityId = @facilityId
-- 			  AND asset.PointId = @pointId

-- 		UPDATE staff set assignedToAsset = @pointId  
-- 			FROM MRA3.TempSchedulerStaffSchedule staff 
-- 			WHERE staff.facilityId = @facilityId
-- 				AND staff.staffId = @staffId 
-- 				AND staff.schedDate = @date
		
-- 		-- finally, remove all place preferences made by this staff member AND ALSO all place requests for this point
-- 		DELETE FROM #staffPlaceRequests where staffId = @staffId OR pointId = @pointId OR rowNum = @minRowNum

