-- 								,[FacilityId]
-- 								,[FunctionPlaceStatusMapId]
-- 								,[FunctionId]
-- 								,[PlaceId]
-- 								,[FunctionStatusId]
-- 								,[Data]
-- 								,[TopPriorityParams]
-- 								,[BottomPriorityParams]
-- 								,[PlaceType]
-- 								,[isActive]
-- 								,[updatedAt]
-- 								,[removed])
-- 							VALUES
-- 								(@tenantId,@facilityId,newid(),@functionId,@placeId,@functionStatusId,@data,@topPriorityParams,@bottomPriorityParams,@placeType,1,getdate(),0)
-- 					END
-- 				ELSE
-- 					BEGIN
-- 						UPDATE [MR3].[FunctionPlaceStatusMap] SET
-- 								[FunctionStatusId] = @functionStatusId,
-- 								[Data] = coalesce(@data,[Data]),
-- 								[TopPriorityParams] = coalesce(@topPriorityParams,TopPriorityParams),
-- 								[BottomPriorityParams] = coalesce(@bottomPriorityParams, BottomPriorityParams),
-- 								updatedAt = getdate()
-- 							WHERE PlaceId = @placeId AND FunctionId = @functionId
-- 					END
-- 				FETCH NEXT FROM xCrsr into @placeId,@functionId,@functionStatusId,@data, @topPriorityParams, @bottomPriorityParams, @placeType
-- 			END

-- 			CLOSE xCrsr
-- 			DEALLOCATE xCrsr
-- 	END


-- END


