-- 			DECLARE @roles nvarchar(4000)

-- 			SELECT @staffId = i.staffId, @facilityId = i.assignedToFacilityId, @roles = i.staffRoles FROM INSERTED i

-- 			-- first remove any records that should not be included
-- 			DELETE FROM MR3.StaffFunctionRoleMap WHERE StaffFunctionRoleMapId IN
-- 			(SELECT 
-- 				sfrm.StaffFunctionRoleMapId
