-- 			left outer join MR3.StaffFunctionRoleMap sfrm on sfrm.staffId = @staffId and sfrm.FunctionRoleId = r00t.FunctionRoleId
-- 			WHERE fr.FacilityId = @facilityId 
-- 				AND LOWER(r00t.FunctionRoleCode) not in (SELECT TRIM(value) FROM STRING_SPLIT(LOWER(@roles),','))
-- 				AND sfrm.StaffFunctionRoleMapId IS NOT NULL)

-- 			-- then insert new records that need to be added
-- 			INSERT MR3.StaffFunctionRoleMap (StaffId,FunctionRoleId,TenantId,isActive,updatedAt,removed)
-- 			SELECT 
-- 				@staffId,
-- 				fr.FunctionRoleId,
-- 				fr.TenantId,
-- 				1,
-- 				getdate(),
-- 				0 
-- 			FROM MR3.FunctionRole fr
-- 			inner join MR3.FunctionRole r00t on r00t.FunctionRoleId = fr.FunctionRoleRootId
-- 			left outer join MR3.StaffFunctionRoleMap sfrm on sfrm.staffId = @staffId and sfrm.FunctionRoleId = r00t.FunctionRoleId
-- 			WHERE fr.FacilityId = @facilityId 
-- 				AND LOWER(r00t.FunctionRoleCode) in (SELECT TRIM(value) FROM STRING_SPLIT(LOWER(@roles),','))
-- 				AND sfrm.StaffFunctionRoleMapId IS NULL
	
	
-- 		    -- now convert all of the roles for the updated staff member into
-- 			-- comma separated strings and update the staff record
-- 			SELECT @roles = STRING_AGG (frRoot.FunctionRoleCode,', ') from MR3.StaffFunctionRoleMap sfrm
-- 			INNER JOIN MR3.FunctionRole fr on sfrm.FunctionRoleId = fr.FunctionRoleId
-- 			INNER JOIN MR3.FunctionRole frRoot on frRoot.FunctionRoleId = fr.FunctionRoleRootId
-- 			where sfrm.StaffId = @staffId and fr.FacilityId = @facilityId

-- 			UPDATE MR3.Staff SET staffRoles = @roles, updatedAt = getdate() WHERE StaffId = @staffId
	
-- 	END




