-- CREATE TRIGGER [MR3W].[tgUpdateSurveyFunctionRoleMap] ON [MR3W].[vwSurveyFunctionRoleMap]
-- INSTEAD OF UPDATE, INSERT, DELETE AS
-- BEGIN

-- 	SET NOCOUNT ON

-- 	IF EXISTS(SELECT * FROM DELETED) AND NOT EXISTS(SELECT * FROM INSERTED)
-- 		BEGIN
-- 			 DELETE	FROM MR3.SurveyFunctionRoleMap WHERE SurveyFunctionRoleMapId in (SELECT SurveyFunctionRoleMapId from DELETED)
-- 		END
-- 	ELSE IF EXISTS(SELECT * FROM DELETED) AND EXISTS(SELECT * FROM INSERTED)
-- 		BEGIN
-- 			UPDATE [MR3].[SurveyFunctionRoleMap]
-- 			   SET 

-- 			   [TenantId]						= i.[TenantId]
-- 			  ,[SurveyId]						= i.[SurveyId]
-- 			  ,[FunctionRoleId]					= i.[FunctionRoleId]
-- 			  ,[isActive]						= i.[isActive]
-- 			  ,[updatedAt]						= getdate()
-- 			  ,[removed]						= i.[removed]

-- 			 FROM MR3.SurveyFunctionRoleMap s
-- 			 inner join INSERTED i on i.SurveyFunctionRoleMapId = s.SurveyFunctionRoleMapId
-- 		END
-- 	ELSE IF NOT EXISTS(SELECT * FROM DELETED) AND EXISTS(SELECT * FROM INSERTED)
-- 		BEGIN
-- 		INSERT INTO [MR3].[SurveyFunctionRoleMap]
-- 				   (
-- 					   [TenantId]
-- 					  ,[SurveyId]
-- 					  ,[FunctionRoleId]
-- 					  ,[isActive]
-- 					  ,[updatedAt]
-- 					  ,[removed]
-- 				   )
     
-- 				   SELECT 
-- 					   [TenantId]
-- 					  ,[SurveyId]
-- 					  ,[FunctionRoleId]
-- 					  ,[isActive]
-- 					  ,getdate()
-- 					  ,[removed]
-- 					FROM INSERTED

-- 		END

-- 	DECLARE @surveyId uniqueidentifier,
-- 	@roles nvarchar(4000)

-- 	DECLARE rCrsr CURSOR FOR 
-- 		SELECT SurveyId FROM INSERTED
-- 		UNION
-- 		SELECT SurveyId FROM DELETED

-- 	OPEN rCrsr

-- 	FETCH NEXT FROM rCrsr into @surveyId

-- 	WHILE @@FETCH_STATUS = 0
-- 	BEGIN
		
-- 		-- now convert all of the roles for the updated survey records into
-- 		-- comma separated strings and update the survey record
-- 		SELECT @roles = STRING_AGG (frRoot.FunctionRoleCode,',') from MR3.SurveyFunctionRoleMap sfrm
-- 		INNER JOIN MR3.FunctionRole fr on sfrm.FunctionRoleId = fr.FunctionRoleId
-- 		INNER JOIN MR3.FunctionRole frRoot on frRoot.FunctionRoleId = fr.FunctionRoleRootId
-- 		WHERE sfrm.SurveyId = @surveyId

-- 		UPDATE MR3.Survey SET surveyRoles = @roles, updatedAt = getdate() WHERE SurveyId = @surveyId
	
-- 		FETCH NEXT FROM rCrsr into @surveyId
-- 	END

-- 	CLOSE rCrsr
-- 	DEALLOCATE rCrsr

-- END
